use super::*;

/// Compare a store's current counts against a committed baseline. Returns the drift violations — a record
/// that appears with >1 leaf and is NOT in the baseline (a NEW multi-method record), or a baselined record
/// whose count has GROWN. Grandfathers the backlog: a baselined record at or below its baseline is fine.
pub fn drift_against(current: &BTreeMap<String, usize>, baseline: &BTreeMap<String, usize>) -> Vec<String> {
    let mut violations = Vec::new();
    for (id, &n) in current {
        match baseline.get(id) {
            None => violations.push(format!("{id}: NEW multi-method record with {n} extractable leaves (baseline has none)")),
            Some(&b) if n > b => violations.push(format!("{id}: extractable leaves grew {b} -> {n}")),
            Some(_) => {}
        }
    }
    violations.sort();
    violations
}
